-- ========================================================
-- Expense Tracker Database Schema (MySQL 8.0+)
-- Auto-generated by Hibernate or executable manually
-- ========================================================

CREATE DATABASE IF NOT EXISTS `expense_tracker_db` 
CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `expense_tracker_db`;

-- 1. Users Table
CREATE TABLE IF NOT EXISTS `users` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `full_name` VARCHAR(100) NOT NULL,
    `email` VARCHAR(100) NOT NULL UNIQUE,
    `password` VARCHAR(255) NOT NULL,
    `bank_balance` DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
    `cash_balance` DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2. Categories Table
CREATE TABLE IF NOT EXISTS `categories` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `name` VARCHAR(50) NOT NULL,
    `type` VARCHAR(10) NOT NULL, -- 'EXPENSE' or 'INCOME'
    `user_id` BIGINT NOT NULL,
    CONSTRAINT `fk_category_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 3. Payment Modes Table
CREATE TABLE IF NOT EXISTS `payment_modes` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `mode_name` VARCHAR(50) NOT NULL,
    `account_type` VARCHAR(10) NOT NULL, -- 'CASH' or 'BANK'
    `user_id` BIGINT NOT NULL,
    CONSTRAINT `fk_payment_mode_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 4. Transactions Table
CREATE TABLE IF NOT EXISTS `transactions` (
    `id` BIGINT AUTO_INCREMENT PRIMARY KEY,
    `amount` DECIMAL(15, 2) NOT NULL,
    `type` VARCHAR(10) NOT NULL, -- 'EXPENSE' or 'INCOME'
    `transaction_date` DATE NOT NULL,
    `description` VARCHAR(255) NULL,
    `category_id` BIGINT NOT NULL,
    `payment_mode_id` BIGINT NOT NULL,
    `user_id` BIGINT NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT `fk_transaction_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
    CONSTRAINT `fk_transaction_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
    CONSTRAINT `fk_transaction_payment_mode` FOREIGN KEY (`payment_mode_id`) REFERENCES `payment_modes` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX `idx_transactions_user_date` ON `transactions` (`user_id`, `transaction_date` DESC);
